export const SPELLS = [
    // ---- fight
    { cat: 'fight', name: 'Инферно', say: 'рука к лицу + «Инферно»', desc: 'Поток огня из руки: он идёт за рукой — повернули руку, повернулось и пламя. Горит до 5 с, пока держите: 10 маны сразу и ещё 3 маны в секунду (мана в это время не прибывает; кончилась — пламя гаснет). Жжёт всех, до кого достаёт: игроков, зомби, жителей, рыцарей, волшебников, животных, пауков, живые деревья; поджигает деревья и сухое. Щит «Protection», поднятый навстречу, держит огонь — пламя разбивается о него. Вода (водяной шар, водоворот, река, море) гасит пламя паром — за водой не жжёт. Стена тоже останавливает. Это не дуэльное заклинание. «Стоп» гасит его.', dmg: '1/тик', pvp: '1 каждые 0,6 с', cost: '10 + 3/с', icon: 'assets/icons/inferno.png' },
    { cat: 'fight', name: 'Тандервейв', say: 'рука к лицу + «Тандервейв» / «Гром»', desc: 'Веер молний: всех впереди отбрасывает — людей, зомби, животных. Ближе 20 м сбивает с ног, дальше — отшатнутся.', dmg: '5', pvp: '3 + сбивает с ног (до 20 м)', cost: 15, icon: 'assets/icons/thunder.png' },
    { cat: 'duel', name: 'Даст', say: 'направить поднятую руку на цель + «Даст» / «Санд»', desc: 'Дуэльное заклинание: песчаный заряд летит туда, куда показывает рука. Кому попал — песок в глаза и в суставы: 5 секунд он двигается намного медленнее (любое существо: игрок, зомби, зверь, житель, рыцарь). Можно отбить щитом или встречным заклинанием.', dmg: 'замедление 5 с', pvp: '3 + замедление 5 с', cost: 8, icon: 'assets/icons/sand.png' },
    { cat: 'fight', name: 'Бомбардо', say: 'рука к лицу + «Бомбардо»', desc: 'Взрывной шар: вырывает куски гор и земли, взрывается в кроне дерева (а не пролетает сквозь листву) и ломает деревья, раскидывает зомби, людей, животных и предметы: рядом сбивает с ног и подбрасывает. Рядом с собой — ранит и вас.', max: '(Вне Творческого — только после свитка «Бомбардо Максима», красная лента.) «Бомбардо Максима»: в 3 раза мощнее, огромная волна из руки, воронка намного шире (урон до 24, мана 25).', dmg: 'до 8', pvp: 'урон + сбивает с ног рядом (щит −50%)', cost: 15, icon: 'assets/icons/bombardo.svg' },
    { cat: 'fight', name: 'Earthquake', say: 'обе руки в сторону удара, поднять ногу и топнуть + «Earthquake» (слышится и как «Escape»)', desc: 'Землетрясение бежит по земле: трещина, пыль, камни; земля по-настоящему проваливается вдоль трещины, а всех рядом с волной трясёт. Всё на пути — люди, зомби, животные — падает навзничь и получает урон. Существа встают сами; игроку, чтобы встать, нужно присесть и выпрямиться.', max: '«Earthquake Максима»: три трещины рядом, земля вздыбливается, больше камней и пыли; длиннее (32 м) и шире, урон 12, лежат дольше (мана 25).', dmg: '4', pvp: '3 + сбивает с ног (встать — присесть и выпрямиться)', cost: 10, icon: 'assets/icons/earthquake.svg' },
    { cat: 'fight', name: 'Wind', say: 'поднять руку в нужную сторону + «Wind» или «Вайнд» (одно и то же; «Wind Maxima» / «Вайнд Максима» — сильнее)', desc: 'Сильный порыв ветра (до 14 м): зомби, людей, рыцарей, животных и игроков отбрасывает на несколько метров и сбивает с ног, на самом краю — только отшатнутся. Предметы сдувает. Не ранит. В паруса корабля — ветер дует непрерывно, пока есть мана (−1 в секунду) или до «стоп», и корабль идёт вперёд; «Вайнд Максима» резко толкает корабль с места и разгоняет его гораздо быстрее.', max: '«Вайнд Максима»: в 3 раза сильнее и дальше, до 24 м — всех сбивает с ног и уносит далеко (мана 20).', dmg: '—', pvp: 'отбрасывает и сбивает с ног; на краю — отшатнётесь', cost: 8, icon: 'assets/icons/wind.svg' },
    { cat: 'fight', name: 'Overgrown', say: 'направить поднятую руку на одного или на толпу + «Overgrown» («Овергроун», «Оверграун»)', desc: 'Всех, на кого показывает рука, — зомби, людей, рыцарей, животных, игроков — разбрасывает в стороны от линии заклинания и подкидывает вверх. Само заклинание не ранит: больно только тем, кто из-за него упадёт с высоты (с обрыва, со стены).', max: '(Вне Творческого — только после свитка «Overgrown Максима», салатовая лента.) «Overgrown Максима»: в 2 раза сильнее — дальше и выше, до 24 м (мана 20).', dmg: '—', pvp: 'разбрасывает и сбивает с ног; урон — только от падения с высоты', cost: 10, icon: 'assets/icons/overgrown.svg' },
    { cat: 'fight', name: 'Wind Impulse', say: 'поднять палочку (руку) вверх + «Wind Impulse» («Вайнд Импульс»)', desc: 'Только из свитка (белая лента; один свиток учит и Максиму). Без шара и без луча: из вас во все стороны вырывается кольцо воздуха — видно, как волна расходится по земле. Всех в 3 метрах — людей, зомби, животных, игроков, моряков, феникса — отталкивает от вас (ближних сбивает с ног); вещи на земле разлетаются, лёгкие книги-птицы падают, дракон лишь качнётся. Само не ранит.', max: '«Wind Impulse Максима»: то же на 9 метров (мана 40).', dmg: '—', pvp: 'отталкивает (щит держит)', cost: 10, icon: 'assets/icons/wind.svg' },
    { cat: 'fight', name: 'Drawdown', say: 'направить палочку (руку) на землю + «Drawdown» («Дравдаун»)', desc: 'Земля, на которую показываете, просаживается чашей. Ямка идёт за палочкой: держите палочку на одном месте — яма углубляется (каждые 1.5 с ещё на блок, до 6); ведите палочку по земле — яма тянется за ней. Всё, что на земле стоит, опускается вместе с ней: дома, стены, деревья, сундуки, люди, звери, вещи. Продолжается, пока не скажете «стоп» или не кончится мана: 5 сразу и 1 в секунду. Вода, коренная порода и дом под сферой защиты не проседают. Проседающий замок пугает жителей и злит стражу.', max: '«Drawdown Максима»: чаша шире (радиус 7 м) и глубже (до 9); 20 маны сразу и 2 в секунду.', dmg: '—', pvp: 'опускает вместе с землёй', cost: 5, icon: 'assets/icons/earthquake.svg' },
    { cat: 'fight', name: 'Liquidation', say: 'направить палочку (руку) на вещь + «Liquidation» («Ликвидейшн»)', desc: 'Не луч и не дуэльное: из палочки летит дрожащий серо-сиреневый всплеск и ударяется в первое, что на пути. Неживая вещь — сыр, яблоко, меч, щит, блок стены, доска — рассыпается в прах. Волшебную вещь (палочку, свиток, книгу, волшебное оружие, зелье, кристалл маны, камень башен волшебников) обычный всплеск не берёт — нужна Максима. Живое (игрок, зомби, житель, животное, дерево) — только −3 HP. От «Protection» отражается.', max: '«Liquidation Максима»: рассыпает и волшебные вещи (мана 25).', dmg: '3', pvp: '3 (щит держит)', cost: 10, icon: 'assets/icons/sand.png' },
    { cat: 'fight', name: 'Lightning Strike', say: 'обе руки вверх + «Lightning Strike»', desc: 'Очень сложное: 5 с небо темнеет, потом молния бьёт вам в руки. Плавно наведите руку на цель и задержите — молния ударит туда. Не успели — ударит в вас. Кто выжил — падает с ног.', dmg: '20', pvp: '12 + сбивает с ног', cost: 25, icon: 'assets/icons/thunder.png' },
    { cat: 'fight', name: 'Total Destruction', say: 'направить поднятую руку на замок, дом или место + «Total Destruction» («Тотал Дестракшн»)', desc: 'Самое разрушительное заклинание — в 5 раз сильнее «Бомбардо Максима», но без снаряда и без вспышек. Там, куда показывает рука (круг около 20 м), содрогается земля: всё трясётся всё сильнее, летят пыль и камни, стены трескаются — и через 3 с всё построенное (замки, дома, стены, башни, деревья) само рассыпается. Остаются руины: обломки стен и завалы камней, земля немного проседает (но ямы нет). Пещеры там (и под этим местом) обваливаются: потолок рушится, на полу — груды камней, тонкий свод проваливается до неба. Все существа там падают с ног и сильно ранены. Только для тех, у кого <b>максимум маны 100 и больше</b>. Вне Творческого режима — только после свитка «Total Destruction» (чёрная лента, очень редкий).', max: '«Total Destruction Максима»: в 2 раза сильнее — круг около 28 м, земля трясётся дольше, урон вдвое больше. Нужен максимум маны 200, стоит 160 маны; учится из того же свитка.', dmg: 'до 120', pvp: 'до 150 + сбивает с ног', cost: 80, icon: 'assets/icons/total_destruction.svg' },
    { cat: 'fight', name: 'Circle Attack', say: 'развести руки в стороны, как буква T (как для «Protection Maxima»), + «Circle Attack» («Сёркл Аттак»; сильнее — «Circle Attack Maxima» / «Сёркл Аттак Максима»)', desc: 'Чрезвычайно сложное заклинание: из волшебника исходит вся магия. Вокруг него вырастает огромный золотой шар света с лучами и волной катится во все стороны (30 м): кого он достиг — сбивает с ног и отбрасывает, и чем ближе вы были, тем дальше улетите. Урон: вблизи −30, на середине −20, на краю −10. Земля под шаром рушится и вздымается кругами, как при землетрясении, дома и стены обрушаются — не сразу, а вслед за шаром: всё длится 7 секунд, так что дальние успевают спрятаться. Из волшебника бьют лучи света в 3–5 случайных существ (−10 каждому). Сам волшебник стоит на маленьком светящемся островке — его волна не трогает. Звучит своя музыка. Нужен <b>максимум маны 100</b>.', max: '«Circle Attack Maxima»: круг 45 м, урон −45 / −30 / −15, лучей 5–8 по −15, отбрасывает в полтора раза дальше. Нужен максимум маны 200, стоит 160 маны.', dmg: '30 / 20 / 10 + лучи 10', pvp: '30 / 20 / 10 + сбивает с ног', cost: 80, icon: 'assets/icons/circle_attack.svg' },
    { cat: 'fight', name: 'Inspirius', say: 'палочка в руке (в Творческом — и без неё) + «Inspirius» («Инспириус»)', desc: 'Сложнейшее и самое могущественное заклинание — в 10 раз разрушительнее «Total Destruction Maxima». Направьте всю силу в палочку: из неё вылетает живой электрический шар света (не Люмос — он трещит молниями) и летит около 5 секунд туда, куда смотрит палочка, — пока палочка показывает, им можно рулить. Коснувшись чего угодно (земли, стены, существа, воды), он взрывается: ослепительная вспышка, столб света в небо, молнии, огненный шар и ударная волна. Остаётся огромная яма — чем ближе к центру, тем глубже; всё построенное до 45 м рушится, по краю загорается. Урон: до 20 м −100, до 40 м −50, до 60 м −25, всех сбивает с ног и отбрасывает. Вне Творческого — только после свитка «Inspirius» (сияющая бело-голубая лента), а он попадается только тем, у кого <b>максимум маны уже 500</b>.', dmg: '100 / 50 / 25', pvp: '100 / 50 / 25 + сбивает с ног', cost: 500, icon: 'assets/icons/inspirius.svg' },
    { cat: 'fight', name: 'Let the Hellfire Come', say: 'палочка в руке (в Творческом — и без неё) + «Let the Hellfire Come» («лет зе хеллфаер кам»; можно «Hellfire come», «Come, hellfire»)', desc: 'Вне Творческого — только после свитка «Let the Hellfire Come» (багровая лента) из сундука. Скажите всю фразу, со словом «Come» («кам») в конце. Да придёт адский огонь — самое сильное огненное заклинание. Из палочки вырывается огромная живая масса огня: она пульсирует, растёт и стоит там, куда показывает палочка, и плывёт за ней. Вы управляете ею рукой: согнутая рука — огонь близко, вытянутая — далеко (до 18 м); чем дольше держите, тем огонь больше, а разведёте руки шире — ещё больше (сведёте — меньше). Огонь сжигает всех, до кого дотянется: зомби, жителей, рыцарей, волшебников, животных, пауков, живые деревья; жар обжигает и тех, кто рядом (даже за щитом и в доспехах — щит и броня лишь ослабляют, а щит в огне раскаляется); дыхание огня отбрасывает тела, резкий взмах пламени сбивает с ног. Огня боятся: жители и животные бегут, рыцари и волшебники пятятся за щитами, некоторые в панике бегут; поджигает деревья (от них огонь перекидывается дальше), траву и всё сухое. <b>Крутите рукой по кругу</b> — огонь уходит в кольцо вокруг вас: ревущая стена пламени и огненные змеи несутся вокруг так быстро, как идёт ваша рука, и жгут всех рядом. С каждым новым оборотом руки кольцо расползается всё шире: оно дальше от вас, стена огня толще и выше, змей больше — до огромного кольца шириной около 40 м. Перестали крутить и показали рукой — огонь возвращается туда. <b>Огонь опасен и для вас</b>: направите его на себя (себе под ноги), раздуете так, что он дойдёт до вас, или войдёте в него — сгорите. Щит «Protection» лишь вдвое ослабляет жар — огонь обходит щит. Вода гасит его: водяной шар, водоворот, река или море — огонь шипит паром и съёживается, а утопленный — гаснет; кто стоит в водяной магии, не горит. Только для тех, у кого <b>максимум маны 100 и больше</b>: 80 маны сразу и 2 маны в секунду, пока горит (мана в это время не прибывает). Остановить его можно словом «стоп», но это стоит <b>50 маны</b>; если 50 маны нет, огонь не остановить — он горит, пока не кончится мана. Остановленный (или когда кончилась мана) огонь больше не растёт, не идёт за рукой и не кружит: он распадается на костры на земле там, где был, и они горят <b>ещё не меньше 30 секунд</b>, потом угасают, — и жгут всякого, кто в них войдёт, вас тоже. Что загорелось (деревья, трава, деревянное), догорает до конца само. Впервые по-настоящему что-то подожгли — <b>+20 к максимуму маны</b> (один раз). В Творческом режиме мана не нужна.', dmg: '4 каждые 0,25 с в огне, жар рядом — до 2', pvp: '2 каждые 0,5 с в огне, 1 в секунду рядом (щит — вдвое меньше), и вам тоже', cost: '80 + 2/с, «стоп» 50', icon: 'assets/icons/inferno.png' },
    { cat: 'fight', name: 'Брейнрот', say: 'посмотреть на существо + «Брейнрот»', desc: 'Гипнотические кольца — любое существо (зомби, корова, лошадь, житель, рыцарь, волшебник, чужое живое дерево) становится вашим слугой на 45 с: ходит за вами на небольшом расстоянии, защищает и бьёт ваших врагов. Направьте руку на кого-то и скажите «Атак» — слуги пойдут на него.', dmg: '—', cost: 15, icon: 'assets/icons/brainrot.svg' },
    { cat: 'move', name: 'Give Me My Power', say: 'поднять руку (палочку) и направить на свой скелет + «Give Me My Power» («Гив ми май пауэр», «Верни мне мою силу»)', desc: 'Только из свитка (тёмно-золотая лента). Когда вы погибаете, вся ваша сила остаётся в вашем теле: ячейки маны, свитки, выученные заклинания, полёт, ачивки. Найдите свой скелет (над ним золотые искры) и скажите это заклинание, указав на него рукой, — всё прежнее вернётся к вам. Действует только на ваш собственный скелет. Само заклинание смерть не забирает.', cost: 50 },
    { cat: 'move', name: 'Snowman', say: 'направить поднятую руку (палочку) на снег + «Snowman» («Сноумен», «Снеговик»)', desc: 'Снег, на который показывает рука, сам собирается в три кома, они складываются друг на друга, появляются глаза-угольки, нос-морковка, руки-веточки и красный шарф — снеговик моргает, оглядывается и оживает. Он добрый и ничей: не слушается вас, никого не атакует и не держит вашу концентрацию — «стоп» его не убирает. Просто неспешно бродит туда-сюда, держится снега и смотрит на тех, кто рядом. Боится жары: от костра, пожара, огня и взрывов убегает, рядом с огнём тает и становится меньше, а сильный огонь растапливает его в лужицу. 10 HP: удары, стрелы и простые заклинания рассыпают его, лёд и холод ему не страшны. Злые снеговики и Ледяная Королева его не трогают. Остаётся в мире, пока не растает. Работает только на снегу (снежные вершины гор). Можно и без свитка; в Творческом — бесплатно.', dmg: '—', cost: 30, icon: 'assets/icons/snowman.svg' },
    { cat: 'fight', name: 'Alive', say: 'направить поднятую руку на дерево или могилу + «Alive» («Алайв»)', desc: 'Дерево оживает: за 3 секунды ветки становятся руками с пальцами-прутьями, в коре загораются страшные глаза и рот с зубами, корни вылезают из земли — и дерево встаёт. Оно ваш слуга: ходит за вами, охраняет и бьёт ветками ваших врагов. Направьте руку на кого-то и скажите «Атак» — дерево пойдёт на него. Живёт, пока у вас есть мана: мана не восстанавливается и тратится (0,5 в секунду). Кончилась мана, вы ушли дальше 50 м или сказали «стоп» — дерево деревенеет и падает: остаётся поваленное дерево, его можно собрать «Gather». 15 HP, убивает его огонь (Инферно, костёр, горение), молния, «Бомбардо» и «Бомбардо Максима» (разрывают его в щепки) и самые мощные заклинания (Total Destruction, Circle Attack, Inspirius) — «Авада Кедавра» не действует, меч и топор не ранят, но сильным ударом кромкой можно отрубить ему ветку-руку (ею оно больше не бьёт). Золотые деревья не оживают. На кладбище у деревни направьте руку на могилу и скажите «Alive» — мертвец встаёт не сразу: могила трясётся, из земли поднимается костлявая рука, земля разверзается — и из ямы с зелёным светом вылезает скелет. Он такой же слуга, как живое дерево (та же мана, концентрация, 15 HP, бьёт ваших врагов), но он не совсем живой: «Авада Кедавра» и другие дуэльные заклинания его не убивают — разрушают огонь, «Бомбардо», молния, самые мощные заклинания, а ещё меч, топор и кулаки (кости ломаются). Когда магия уходит — он рассыпается на кости. Разрытая могила остаётся пустой. Вне Творческого режима — только после свитка «Alive» (коричневая лента).', dmg: 'ветки −4', cost: 25, icon: 'assets/icons/alive.svg' },
    { cat: 'fight', name: 'Alive Максима', say: 'направить поднятую руку на дерево или могилу + «Alive Максима»', desc: 'Как «Alive», только вдвое дороже — и оживает всё вокруг сразу. На кладбище встают все мертвецы из неразрытых могил (по очереди: могилы трясутся, поднимаются руки, земля разверзается). В лесу оживает дерево, на которое вы показали, и деревья рядом с ним (в радиусе 14 м, всего до 6). Каждый оживший тратит 1 ману в секунду: сколько оживили — столько маны в секунду и уходит. Кончилась мана, «стоп», вы ушли дальше 50 м или сорвалась концентрация — все они разом рассыпаются / деревенеют. Вне Творческого режима — после свитка «Alive».', dmg: 'как у «Alive»', cost: 50, icon: 'assets/icons/alive.svg' },
    // ---- duel
    { cat: 'duel', name: 'Айс', say: 'направить поднятую руку на цель + «Айс» / «Лёд»', desc: 'Дуэльное заклинание: ледяной кристалл летит по морозному лучу туда, куда показывает рука, и при попадании заковывает цель в лёд. Существа (зомби, звери, жители, рыцари) стоят во льду и не двигаются; игрок в режиме «Выживание» заморожен на 20 секунд, и любой удар по нему смертелен, в других режимах — 5 секунд. Можно отбить щитом или встречным заклинанием. Срабатывает только на отдельное слово «Айс» — не от обычной речи.', dmg: 'заморозка', pvp: 'заморозка 20 с', cost: 10, icon: 'assets/icons/ice.png' },
    { cat: 'duel', name: 'Сапира', say: 'направить поднятую руку на цель + «Сапира»', desc: 'Медленный тяжёлый фиолетовый заряд: сбивает с ног. Его можно отбить щитом или встречным заклинанием.', dmg: '10', pvp: '4', cost: 20, icon: 'assets/icons/sapira.png' },
    { cat: 'duel', name: 'Остолбеней', say: 'направить поднятую руку + «Остолбеней»', desc: 'Летящий заряд светит своим цветом — освещает стены пещеры, землю и существ рядом (видно всем игрокам). Красный заряд быстро летит к цели. Попал — цель падает навзничь и 15 секунд не двигается. Существа потом встают сами, игрок — присев и выпрямившись.', dmg: 'оглушение 15 с', pvp: 'оглушение 15 с', cost: 12, icon: 'assets/icons/stupefy.svg' },
    { cat: 'duel', name: 'Экспеллиармус', say: 'направить поднятую руку на волшебника + «Экспеллиармус»', desc: 'Тёмно-алый заряд с белой серединой летит туда, куда показывает рука. Попал в волшебника с палочкой — палочка вылетает из руки, кувыркаясь, и падает в 4–10 метрах в случайную сторону (не сквозь стены). Её может подобрать кто угодно — и вы тоже. Без палочки можно колдовать, но слабее. Волшебники башен бегут за своей палочкой; успели забрать раньше — она ваша. У рыцаря вылетает меч, и он дерётся кулаками. Остальных (зомби, звери, моряки) только толкает; на живое дерево и паучиху не действует. Можно отбить щитом или встречным заклинанием — тогда дуэль, и проигравшему достаётся заклинание победителя.', dmg: 'выбивает палочку / меч', pvp: 'выбивает палочку', cost: 12, icon: 'assets/icons/expelliarmus.svg' },
    { cat: 'duel', name: 'Disarmor', say: 'направить поднятую руку на того, кто в латах + «Disarmor» («дизармор»; можно «раздеть»); чтобы снять с себя — поднять палочку (руку) вверх, к небу, + «Disarmor»', desc: 'Стальной серо-голубой заряд летит туда, куда показывает рука. Попал в рыцаря или короля — вся его обычная металлическая броня (шлем, нагрудник, поножи) слетает и разлетается в разные стороны настоящими вещами: их можно подобрать или надеть. Рыцарь дерётся дальше, но уже без брони. С волшебника слетает обычная мантия. С игрока — его обычные доспехи и обычная мантия. Волшебные доспехи и волшебную мантию не снять. Кого задел, того ещё и отбрасывает с кувырком и роняет, как «Джолт»; зомби, звери и моряки только отлетают. На паучиху, дракона и живое дерево не действует. Можно отбить щитом или встречным заклинанием. На себя: поднимите палочку (в Творческом — руку) вверх, к небу, и скажите «Disarmor» — ваши обычные доспехи и обычная мантия упадут рядом, их можно подобрать; волшебное и костюм Высшего мага останутся на вас. Мана — как обычно.', dmg: 'снимает обычные латы', pvp: 'снимает обычные доспехи', cost: 12, icon: 'assets/icons/disarmor.svg' },
    { cat: 'duel', name: 'Джолт', say: 'направить поднятую руку на цель + «Джолт»', desc: 'Дуэльное заклинание-толчок: почти невидимый сгусток воздуха (видна только дрожащая рябь и прозрачные кольца) летит туда, куда показывает рука. Кому попал — того отбрасывает далеко назад: он кувыркается в воздухе, падает и лежит несколько секунд. Существа потом встают сами, игрок — присев и выпрямившись. После этого голова кружится: у игрока плывёт картинка и шатает при ходьбе, существа шатаются и спотыкаются, волшебник мажет. Само заклинание не ранит — больно, только если сбросить с обрыва, со стены или за борт корабля. Тяжёлые (рыцарь, корова, лошадь) отлетают ближе; летящую свинью или пегаса сбивает с неба, книгу-птицу — тоже; живое дерево и паучиха только пошатнутся. Лежащие на пути вещи отлетают, а то, что в руках, не выпадает. Можно отбить щитом или встречным заклинанием — тогда дуэль.', dmg: 'толчок, падение', pvp: 'толчок, падение, головокружение', cost: 5, icon: 'assets/icons/jolt.svg' },
    { cat: 'duel', name: 'Джолт Максима', say: 'направить поднятую руку на цель + «Джолт Максима»', desc: 'То же, что «Джолт», но в три раза сильнее и в три раза дороже: цель улетает гораздо дальше и выше, делает в воздухе пару кувырков, дольше лежит и дольше не может прийти в себя.', dmg: 'сильный толчок, падение', pvp: 'сильный толчок, падение, головокружение', cost: 15, icon: 'assets/icons/jolt.svg' },
    { cat: 'duel', name: 'Авада Кедавра', say: 'направить поднятую руку + «Авада Кедавра»', desc: 'Зелёный заряд — при попадании сразу −25 HP (не убивает наверняка). Вне Творческого режима — только после свитка «Авада Кедавра» (зелёная лента) из сундука. Это самый редкий свиток.', dmg: '25', pvp: '25', cost: 25, icon: 'assets/icons/avada.svg' },
    { cat: 'duel', name: 'Максима в дуэли', say: 'пока заряды давят друг на друга, крикните «Максима»', desc: 'Ваш напор сильнее: точка встречи ползёт к сопернику быстрее (+5% за каждый крик, складываются). Не чаще раза в 3 секунды. Пока идёт дуэль, каждый теряет 1 ману в секунду.', dmg: '—', pvp: '+5% напора', cost: 5, icon: 'assets/icons/thunder.png' },
    // ---- guard
    { cat: 'guard', name: 'Suit Up', say: '«Suit Up» («сьют ап»; можно «одеть всё»)', desc: 'Известно сразу, без свитка. Надевает весь комплект сразу: лучшие шлем, нагрудник, поножи и мантию из ваших ячеек и из того, что лежит рядом (метров 9) — например, латы убитого рыцаря или мантию убитого волшебника. Надетое раньше уходит в ячейку. Без заклинания тоже можно: возьмите вещь в руку и приложите к своей голове, груди или бедру (поножи).', dmg: '—', pvp: '—', cost: 5, icon: 'assets/icons/suit_up.svg' },
    { cat: 'guard', name: 'Protection', say: 'вытянуть руку + «Protection»', desc: 'У вытянутой руки большой голубой щит: заклинания отскакивают, взрыв рядом ранит вполовину, стрелы и брошенные вещи отлетают от него назад. Сразу −5 маны, потом держится, пока есть мана (−0,5 в секунду, мана не восстанавливается). Каждое заклинание, которое он остановил, снимает с вас половину своей цены (Авада Кедавра 25 → −12,5 маны); не хватило маны — щит разбивается, и это заклинание попадает в вас. Щит держит та рука, которой вы его поставили: если в ней палочка, любое другое заклинание этой палочкой сразу собьёт щит — поэтому поднимите другую руку и скажите «Protection» ею, а палочкой атакуйте. Снять раньше: резко дёрнуть рукой или сказать «стоп».', dmg: '—', cost: 5, icon: 'assets/icons/shield.svg' },
    { cat: 'guard', name: 'Protection Maxima', say: 'руки в стороны буквой «T» + «Protection Maxima»', desc: 'Голубой шар вокруг всего тела: отражает заклинания со всех сторон, взрывы ранят на 75% слабее, стрелы отлетают от него. Сразу −20 маны, потом держится, пока вы не скажете «стоп» или пока не кончится мана (−1 в секунду). Каждое остановленное заклинание снимает половину своей цены; не хватило маны — шар разбивается, и заклинание проходит. Он не в руке: палочкой можно колдовать дальше, шар не пропадёт.', dmg: '—', cost: 20, icon: 'assets/icons/shield_max.svg' },
    // the sphere of protection: only from the book of protection (HouseWards.js); a house is what it is mostly for
    { cat: 'guard', name: 'Invisibility', say: 'навести палочку на себя (или поднять вверх) + «Invisible» («Инвизибл»)', desc: 'Только из свитка (сиреневая лента). 20 маны сразу и 1 в секунду. Вас не видят другие игроки и ни одно существо — жители, рыцари, волшебники, моряки, зомби, животные, паучиха, драконы, фениксы: они знают только, где вы примерно были, когда что-то сделали (заклинание, удар), идут туда, бьют туда — и быстро теряют. Сами вы себя видите чуть-чуть, полупрозрачно. Ваши заклинания видны всем. Кончилась мана — снова видно; «стоп» — снять.', dmg: '—', cost: 20, icon: 'assets/icons/ward.svg' },
    { cat: 'guard', name: 'Protection House', say: 'направить палочку (руку) на дом — или на всё, что хотите защитить, — + «Protection House» («Протекшн Хаус»), держать палочку на куполе, пока он растёт, потом «стоп»', desc: 'Купол защиты. Из палочки вылетает серебристо-голубой заряд, как у дуэльных заклинаний, и летит в дом. Дом он не ломает: там, где он попал, вспыхивает маленький купол защиты (1,5 м). Пока вы держите палочку на куполе или на доме под ним, он сам растёт — 1 м в секунду; пока растёт, его видно даже сквозь стены: мерцает, по краю бегут искры, светится кольцо на земле и тихо гудит, 3 маны за каждый метр; «Максима» кричать не нужно. Отвели палочку или опустили руку — купол ждёт, навели снова — растёт дальше. Накрыл весь дом — скажите «стоп»: купол вспыхнет, щёлкнет и останется таким. Кончилась мана — купол остаётся, каким успел вырасти (до 24 м). «Protection House Maxima» (или «Максима», пока он растёт) — растёт вдвое быстрее, мана за метр та же. Это шар, разрезанный землёй: над землёй стоит купол, а нижняя половина уходит под землю — подкопаться снизу тоже нельзя. Защитить можно что угодно: покажете на дом — купол встаёт над всем домом, покажете на сундук, лагерь, дерево или просто на землю — над этим местом. Потом его не видно. Но когда к нему подходит тот, кому нельзя, защита вдруг вспыхивает — переливающийся купол с сотами там, где он стоит, — и держит его, как стена: пройти нельзя. Кто давит на неё дольше пары секунд или бежит в неё с разгона, того она отталкивает и снимает 2 HP (раз в секунду; в Творческом без урона). Так со всеми: игроки, жители, рыцари, зомби, звери, моряки, паучиха, драконы, чужие слуги (живое дерево только отталкивает). Хозяин и те, кого он пустил, проходят свободно. Заклинания снаружи разбиваются о неё: дуэльные заряды (и «Авада»), лучи, пламя «Инферно», молния, стрелы, водяные и ледяные шары, толчки ветра; взрывы не ломают то, что внутри, огонь внутри не загорается, земля под ней не проседает. Изнутри колдовать наружу можно. Разрушают её только «Total Destruction» и «Inspirius» — сразу, «Бомбардо Максима» — одним взрывом, «Бомбардо» — примерно тремя (от каждого трещины; если оставить в покое на минуту, они медленно зарастают), «Let the Hellfire Come» — если держать огонь на ней 6–8 секунд (сначала она краснеет). Разрушена — разлетается осколками, хозяину и тому, кто её разбил, приходит «Защита дома разрушена!»; хозяин может поставить её заново. Купол сохраняется вместе с миром. Скажете «Protection House» на свой купол ещё раз — он снова растёт. Выучить можно только из книги защиты (тёмно-синяя птица-книга с серебряным щитом).', dmg: '2 HP тому, кто ломится', pvp: 'не пускает внутрь, отталкивает (−2 HP)', cost: '20 + 3 за каждый метр роста', icon: 'assets/icons/ward.svg' },
    { cat: 'guard', name: 'Protection Invisible', say: 'направить руку на сферу защиты (на дом под защитой) + «Protection Invisible» («Протекшн Инвизибл»)', desc: 'Всё, что внутри сферы защиты, прячется: издалека (дальше 6 м от сферы) на этом месте видна только земля и трава, как вокруг, — ни стен, ни дверей, ни вещей, ни тех, кто внутри. Подходите ближе — он медленно проступает и с 3–4 м виден целиком. Так его видят все игроки. Работает только там, где уже стоит «Protection House», и только у хозяина. Скажете ещё раз — всё снова станет видно (бесплатно).', dmg: '—', cost: 15, icon: 'assets/icons/ward.svg' },
    { cat: 'guard', name: 'Protection House Grant', say: 'стоя у своей сферы защиты (или в ней), направить руку на игрока + «Protection House Grant» («Протекшн Хаус Грант»)', desc: 'Этот игрок теперь свободно проходит сквозь вашу защиту туда и обратно, как вы сами. Он тоже видит подсказку, что его пустили. Его слуги проходят вместе с ним.', dmg: '—', cost: 5, icon: 'assets/icons/ward.svg' },
    // ---- water
    { cat: 'water', name: 'Waterbollow', say: 'рука у самой воды + «Waterbollow»', desc: 'Вода поднимается живым шаром и следует за рукой. Резкий рывок — шар падает.', max: '«Максима», пока держите шар: шар втягивает больше воды и растёт (можно повторять).', dmg: 'ледяной шар: 3–10', pvp: 'ледяной шар: 3', cost: 5, icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Water forming', say: '«Water forming», пока вода жидкая', desc: 'Ведите шар — за ним остаются водяные блоки: стены, башни, дома.', dmg: '—', cost: 5, icon: 'assets/icons/water_forming.svg' },
    { cat: 'water', name: 'Frozen', say: '«Frozen» с водным шаром', desc: 'Замораживает шар и всё сформированное: блоки становятся льдом. Без шара работает как «Айс» (дуэльный ледяной заряд).', dmg: '—', cost: 5, icon: 'assets/icons/ice.png' },
    { cat: 'water', name: 'Wave Attack', say: 'стоя у воды, показать рукой НА воду + «Wave Attack»; волна встала — показать рукой, куда ей идти, и толкнуть рукой туда (или задержать руку)', desc: 'Вода в реке, озере или море поднимается настоящей волной прямо перед вами и ждёт, пока рука её держит: она поворачивается за рукой. Толкните рукой — и волна покатится туда, закручивая гребень: кого накроет — сбивает с ног и уносит (людей, зомби, животных, матросов, и вас самих, если встанете перед ней), тащит лежащие вещи, гасит костры и огонь, раскачивает и толкает корабли. По воде идёт далеко, по земле быстро слабеет, о стену разбивается. Потом рассыпается пеной, земля остаётся мокрой. Опустите руку или скажите «стоп» — волна упадёт обратно в воду. Не ранит.', max: '«Wave Attack Максима»: волна почти вдвое шире и выше, идёт дальше (32 м) и сильнее (мана 18).', dmg: '—', pvp: 'сбивает с ног и уносит', cost: 8, icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Water Vortex', say: 'с палочкой в руке (в Творческом — и без неё) у воды показать НА воду + «Water Vortex» («вотер вортекс»), потом крутить рукой по кругу', desc: 'Очень сильное. В первые 3 секунды начните крутить рукой — вокруг вас поднимается целый водоворот: кольцо за кольцом, с промежутками между ними (до 10 колец). Каждый оборот руки добавляет воды, чем быстрее крутите — тем быстрее вода летит за рукой и тем больше её. Остановите руку и покажите цель (или скажите «Атака») — кольца раскручиваются в быструю закрученную струю: она летит точно по линии руки, и её можно доворачивать рукой, пока не кончится вода. Любое существо сбивает водой (не ранит; большой водоворот валит с ног). Поднятый заранее щит «Protection» его останавливает.', max: 'Дальше: «Bubble» (заранее, пока струя льётся или ещё 4 с после) — цель плавно поднимается в водяном пузыре; шар сам плавно идёт за рукой, как «Левиоса» (резкий рывок — сбросить) (изнутри спасает «Protection Maxima», руки буквой T). «Frozen» — пузырь замерзает: −1 ❤ в секунду от холода и −1 ❤ без воздуха; спасает только «Fire Maxima».', dmg: 'толчок; во льду −2/с', pvp: 'толчок; во льду −2 ❤/с', cost: 25, icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Water Vortex Super Maxima', say: 'палочка в руке (в Творческом — и без неё), встать у реки, озера или моря, показать палочкой НА воду + «Water Vortex Super Maxima» («вотер вортекс супер максима»)', desc: 'Водяной ответ «Адскому огню» — такой же силы. Работает только там, где много воды (не меньше 150 м³ рядом: большая река, озеро, море — лужи и ручья мало, игра скажет). Вода по-настоящему берётся оттуда: река на глазах мелеет и пустеет. Огромная живая масса воды бурлит и стоит там, куда показывает палочка, и плывёт за ней: вытянутая рука — дальше (до 18 м), согнутая — ближе; пока держите, воды набирается больше, а разведёте руки шире — масса ещё больше. Кого она накроет — сбивает с ног, уносит и топит: зомби, жителей, рыцарей, волшебников, животных. <b>Крутите рукой по кругу</b> — вода превращается в бурю вокруг вас: валы и смерчи воды несутся по кругу так быстро, как идёт рука, и сметают всех рядом. <b>Гасит огонь</b>: «Адский огонь» (и его кольцо, и брошенные костры), горящие деревья и траву, костры, поток «Инферно». Опасна и для вас: направите массу на себя — собьёт с ног и будет топить. Щит вдвое ослабляет. Только для тех, у кого <b>максимум маны 100 и больше</b>: 80 маны сразу и 2 в секунду; «стоп» стоит <b>50 маны</b> (без них буря бушует, пока не кончится мана). Когда она кончается, вода обрушивается: большая волна разбегается по земле и сбивает с ног всех рядом, потом уходит — а река снова наполняется. Впервые по-настоящему что-то сделали (смыли существо, погасили огонь) — <b>+20 к максимуму маны</b> (один раз). В Творческом режиме мана не нужна.', dmg: 'сбивает с ног, тонут: 1', pvp: 'сбивает с ног + 1 каждые 0,6 с (и вам тоже)', cost: '80 + 2/с, «стоп» 50', icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Firefighting', say: 'направить руку (или палочку) на огонь + «Firefighting» («файрфайтинг», «фаер файтинг»)', desc: 'Из руки бьёт облако холодной бело-голубой воды и пара — конусом до 15 метров, туда, куда показывает рука (стена его останавливает). Всё, что горит в этом конусе, сразу гаснет: костёр, горящие деревья, трава, дома и стены, горящее живое дерево, пожар на корабле, пламя «Инферно» (у любого волшебника), огненная спираль «Fire Maxima». Адский огонь («Let the Hellfire Come») сильнее: обычный всплеск только сбивает его — он становится меньше и пару секунд не растёт, а мелкие брошенные огни (куски огненного кольца) гаснут. Чтобы залить адский огонь целиком, нужна «Firefighting Максима». Никого не ранит: людей, зомби и животных только слегка толкает водой, а облитого игрока адский огонь 4 секунды не жжёт.', dmg: '— (только толчок водой)', pvp: 'не ранит; облитого 4 с не жжёт адский огонь', cost: 5, icon: 'assets/icons/firefighting.svg' },
    { cat: 'water', name: 'Firefighting Максима', say: 'направить руку на огонь + «Firefighting Максима» («файрфайтинг максима»)', desc: 'Струя воды, как из пожарного шланга, бьёт из руки 5 секунд: она идёт за рукой — водите рукой, и струя заливает всё, куда вы её направили. Шире и дальше обычной — до 25 метров. Гасит всё, что горит, и даже адский огонь: пока струя на нём, он шипит паром, уменьшается и гаснет (огненное кольцо и брошенные огни тоже). Мокрая книга-птица падает. «Стоп» — выключить струю раньше. Вне Творческого режима — только после свитка «Firefighting Максима» (голубая лента) из сундука: сожгите его «Инферно». Обычный «Firefighting» знают все сразу.', dmg: '— (только толчок водой)', pvp: 'не ранит; облитого 4 с не жжёт адский огонь', cost: 20, icon: 'assets/icons/firefighting.svg' },
    { cat: 'water', name: 'Fire Maxima', say: 'показать рукой + «Fire Maxima» («файр максима»)', desc: 'Золотая огненная спираль летит туда, куда показывает рука (до 22 м), и раскрывается огненным цветком шириной ~6 м: растапливает любой лёд (ледяной пузырь «Water Vortex», ледяные шары и постройки, замороженных), обжигает существ в нём и поджигает деревья. Сказанное изнутри ледяного пузыря — лёд тает вокруг вас за секунду, и вы свободны.', dmg: '6', pvp: '3 (щит спасает)', cost: 20, icon: 'assets/icons/inferno.png' },
    { cat: 'water', name: 'Create a Board', say: 'рука на дерево + «Create a Board»', desc: 'Ствол дерева становится доской для волн (можно и из 8 дерева в руке). Несите её двумя руками за края или одной рукой под мышкой (рука опущена у бока); «Акцио» принесёт её прямо в руки. Отпустить: разожмите обе руки, или бросьте (замах и бросок), или вытяните руку и разожмите. Положите на воду и разожмите руки. Подойдите к доске на воде (или держите её на воде руками), поднимите колено над ней и опустите ногу — вы стоите на ней одной ногой, доска сама повернётся по вам; камера видит вас только до пояса — поднимайте колено до пояса; не видит ног совсем — шагайте на месте у доски; другой ногой гребите (колено вверх-вниз или пяткой назад). Волна подхватила — поставьте вторую ногу и держите равновесие наклоном: влево-вправо — поворот, присесть и руки в стороны — устойчивее. Поднимите ногу с доски — вы в воде. Вне Творческого — из книги птицы-книги или свитка (бирюзовая лента). В Творческом доски стоят на пляжах моря и у пьедесталов.', dmg: '—', cost: 6, icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Air Bubble', say: 'в воде: обе руки к голове + «Air Bubble»', desc: 'Воздушный пузырь вокруг головы — под водой можно дышать 30 секунд. Без него воздуха хватает на 20 секунд, потом −1 HP в секунду. Плавают руками: наверху — кроль (рука вперёд-вверх и вниз к бедру) или брасс (ладони вместе, потом в стороны); посмотрите вниз и гребите — нырнёте; под водой гребите брассом или обеими руками сразу туда, куда смотрите. Без гребков тело держится на воде, а под водой медленно всплывает.', max: '«Air Bubble Максима» (руки буквой T): большой пузырь вокруг всего тела на 90 секунд.', dmg: '—', cost: 4, icon: 'assets/icons/water.svg' },
    // ---- move & things
    { cat: 'move', name: 'Анфёрл', say: 'поднять руку и показать на паруса корабля + «Анфёрл» («анферл», «unfurl»)', desc: 'Паруса на корабле сначала свёрнуты. «Анфёрл» опускает все паруса корабля, на который показывает рука. Чтобы корабль пошёл, нужен ветер: «Вайнд» в паруса — они надуваются вперёд, и корабль идёт вперёд по своему курсу, откуда бы ни дул ветер; ветер дует, пока у вас есть мана (−1 в секунду), пока не скажете «стоп»; потом стихает. Обычный «Вайнд» тянет медленно, корабль тяжёлый — разгоняется не сразу. «Вайнд Максима» — как огромный поток воздуха: резко толкает корабль с места и разгоняет в несколько раз быстрее. Иногда ветер дует и сам. Рулить — штурвал руками: положите ладонь на спицы, сожмите пальцы и ведите руку по кругу.', max: '«Анфёрл Максима»: то же — все паруса корабля (мана 14).', dmg: '—', cost: 6, icon: 'assets/icons/wind.svg' },
    { cat: 'move', name: 'Фёрл', say: 'показать на паруса + «Фёрл» («ферл», «furl», «убери паруса»)', desc: 'Сворачивает паруса мачты — корабль ещё долго идёт по инерции и останавливается.', dmg: '—', cost: 3, icon: 'assets/icons/wind.svg' },
    { cat: 'move', name: 'Up', say: 'лёжа на земле: вытянуть руку вперёд или поднять + «Up» («Ап», «Stand up» / «Стенд ап»); стоя или в воде: поднять руку вверх + «Up»', desc: 'Сбили с ног — вытяните руку вперёд (или поднимите её) и скажите «Up» или «Stand up»: вы сразу встаёте, не дожидаясь и не приседая. В глубокой воде (озеро, море) поднимите вверх руку (одну или обе) и скажите «Up» — вода высоко выбрасывает вас вверх, и вы летите дугой туда, куда показывает поднятая рука: прямо вверх — вверх и обратно в воду, вперёд-вверх — на берег или на палубу корабля; приземляетесь мягко, не падая. Стоя где угодно — на земле, на палубе корабля, на крыше, на верёвочном трапе — поднимите руку и скажите «Up»: вас так же подбрасывает вверх и дугой туда, куда показывает рука. Не работает только в воздухе (нужно от чего-то оттолкнуться) и без поднятой руки. Не работает, если вы остолбенели («Остолбеней») или заморожены.', dmg: '—', cost: 7, icon: 'assets/icons/wind.svg' },
    { cat: 'move', name: 'Флайн', say: 'обе руки вверх + «Флайн»', desc: 'Полёт как у Супермена: рулите корпусом, приземление — направьте себя в землю. «Паузин» — парить на месте. Тратит ману: 2,5 в секунду в полёте, 1,8 — паря на месте (больше, чем восстанавливается). На картах не работает. В «Выживании» — только если сожжёте быструю летающую книгу (голубая, с серебряной каймой): лишь она учит «Флайн», свитков полёта больше нет.', dmg: '—', cost: 10, icon: 'assets/icons/flight.svg' },
    { cat: 'move', name: 'Flying Maxima', say: 'в полёте (после «Флайн») + «Flying Maxima» / «Флайн Максима»', desc: 'Полёт в космос. Открывается само, когда у вас становится 1000 ячеек маны (любым способом: практика, ачивки, «Высший маг», кристаллы, свитки) — «Поздравляем, вы приблизились к силе богов!»; в Творческом известно сразу. Взлетите «Флайн» и скажите «Flying Maxima»: вы уходите вверх всё быстрее, небо темнеет, появляются звёзды, облака уносятся вниз — и вы над круглой Землёй, уходите с её орбиты. В космосе летите так же корпусом, только всё быстрее и быстрее (у планет — медленнее); «Паузин» — зависнуть. Подлетите к Земле — войдёте в атмосферу и окажетесь над тем местом, куда летели (так можно быстро перенестись в другую часть мира). На Луне, Меркурии, Венере, Марсе, Плутоне можно сесть; на планете «Flying Maxima» снова уносит в космос. Подробнее — «Механика игры» → «Космос».', dmg: '—', cost: '30, пока несёт — 1,5/с + «Флайн» 2,5/с (+0,5/с дыхание без воздуха)', icon: 'assets/icons/flight.svg' },
    { cat: 'gods', name: 'Create a Planet', say: 'в космосе: поднятая рука или палочка на скопление метеоритов + «Create a Planet» / «Создай планету»', desc: 'Создать планету из метеоритов. Работает только в космосе и только когда рука (палочка) смотрит на скопление метеоритов — они в поясе астероидов (за Марсом) и в поясе Койпера (за Нептуном); без скопления не из чего — подсказка скажет, где ближайшее. Метеориты стягиваются в одну точку, сталкиваются, раскаляются докрасна, слипаются в шар, он остывает — и на месте скопления по его же орбите вокруг Солнца летит новая планета «Планета <ваше имя>». Хотите своё имя — в течение минуты скажите «Назови …» (например, «Назови Аврора»): так её увидят все и на карте космоса. Она безжизненная: камень и пыль, воздуха нет совсем (дышите магией), тяжесть маленькая (около ×0,2) — взлетать с неё легко, без огня атмосферы. На неё можно сесть и строить. Скопление уходит насовсем — их всего 13 на мир. Учится только со свитка из библиотеки храма богов на Венере (синяя лента со звёздами); в Творческом — сразу и бесплатно. Первое использование: +100 ячеек маны.', dmg: '—', cost: 500, icon: 'assets/icons/planet.svg' },
    { cat: 'gods', name: 'Enlarge Planet', say: 'в космосе рука или палочка на планету (или стоя на ней) + «Enlarge Planet» / «Увеличь планету»', desc: 'Планета становится на 30% больше — и тяжесть на ней на 30% сильнее (той же породы стало больше). Видно, как шар растёт. Одну планету можно увеличить не больше 3 раз (в 2,2 раза). Земля на её поверхности остаётся той же — постройки игроков не ломаются; растёт шар в космосе и его притяжение. Работает на каменных планетах, Луне, созданных планетах и газовых гигантах. Не работает: Солнце, Земля (дом всех — боги не дают), Венера (на ней храм богов — вся планета под их защитой). Свиток — коралловая лента (храм богов на Венере). Первое использование: +100 ячеек маны.', dmg: '—', cost: 100, icon: 'assets/icons/planet.svg' },
    { cat: 'gods', name: 'Terraform Planet', say: 'из космоса рука или палочка на планету, или стоя на ней + «Terraform Planet» / «Терраформируй планету»', desc: 'Сделать планету живой, как Земля, — но не такой же: у неё своя трава (бирюзовая, рыжая или алая), свои деревья (широкие «зонтики» и тонкие «шпили» лиловых, голубых, золотых цветов), свой камень, свои моря (бирюзовые, зелёные или лиловые). Появляется атмосфера: своё небо и облака, дышать можно без маны, вход в её воздух — с огнём, взлёт — как с Земли. Животных нет. Всё решает расстояние до Солнца: слишком близко (как Меркурий) — не получится, воздух выкипит; ближе Венеры — жаркая пустыня (воды нет, лиловые кактусы); от орбиты Венеры до чуть дальше Марса — зелёная зона: леса, моря, озёра; дальше, до Юпитера, — ледяной мир (воздух есть, вода — лёд, снежно-голубой мох, ледяные деревья); ещё дальше (Сатурн, Плутон) — не получится, Солнце не греет: сначала подвиньте планету ближе («Wingardium Leviosa Super Maxima»). Постройки игроков на планете остаются, и там, где стоят игроки, деревья не вырастут. Не работает: Солнце, газовые гиганты (нет земли), Земля, Венера (храм богов), уже терраформированная планета. Свиток — изумрудная лента. Первое использование: +100 ячеек маны.', dmg: '—', cost: 1000, icon: 'assets/icons/planet.svg' },
    { cat: 'gods', name: 'Wingardium Leviosa Super Maxima', say: 'в космосе рука или палочка на планету + «Вингардиум Левиоса Супер Максима»', desc: 'Двигать целую планету по космосу. Как дом в «Левиоса Максима»: планета взята там, где была, и медленно идёт за рукой — туда, куда рука показывает, на том же расстоянии; летите — она летит за вами (тяжёлая: не быстрее 1,6 км/с). «Стоп» — отпустить (сами вы летите дальше): планета остаётся на новой орбите вокруг Солнца, на новом расстоянии от него, и если вы подняли или опустили её, она медленно опускается в общую плоскость орбит (а значит, и в новой зоне для «Terraform Planet»). В Солнце и сквозь другие планеты её не протащить — она останавливается у края. Держится концентрацией (другие заклинания в это время не работают): 100 маны сразу и 3 маны в секунду, пока держите; кончилась мана — планета отпущена. Не работает: Солнце, Земля (её орбита — у всех одна), Луна (идёт вокруг Земли), Венера (храм богов). Свиток — жемчужная лента. Первое использование (когда планета сдвинулась): +100 ячеек маны.', dmg: '—', cost: '100 + 3/с', icon: 'assets/icons/planet.svg' },
    { cat: 'move', name: 'Let it rain', say: 'рука или палочка к небу + «Let it rain»', desc: 'Из руки (палочки) в небо уходит серебристо-голубой волшебный поток, небо затягивают тучи — и начинается настоящая гроза: ливень и молнии вдали, 2 игровых часа (2 минуты). В эту грозу работает Молот Тора. Её видят все игроки. Прекратить раньше можно заклинанием «To the Sun». Вне Творческого режима — только после свитка «Let it rain» (серебряная лента) из сундука.', dmg: '—', cost: 20, icon: 'assets/icons/lumos.svg' },
    { cat: 'move', name: 'To the Sun', say: 'рука к небу (во время дождя) + «To the Sun»', desc: 'Золотой луч из руки уходит в небо, тучи расходятся, льют солнечные лучи — дождь и гроза кончаются. Вне Творческого режима — только после свитка «To the Sun» (оранжевая лента) из сундука.', dmg: '—', cost: 12, icon: 'assets/icons/lumos.svg' },
    { cat: 'move', name: 'Акцио', say: 'поднять руку, указать на предмет + «Акцио»', desc: 'Любая вещь до 30 м (меч, лук, щит, палочка, свиток, еда, монеты) прилетает прямо в свободную руку. Доска для волн большая: две свободные руки — ложится поперёк перед грудью, краем в ладони; одна — под мышку этой руки; руки заняты — падает у ваших ног.', dmg: '—', cost: 5, icon: 'assets/icons/accio.svg' },
    { cat: 'move', name: 'Алохомора', say: 'показать рукой (или палочкой) на замок рядом, до 5 м + «Алохомора»', desc: 'Открывает замок. Сундуки в замках, деревнях и домах жителей теперь заперты: просто подойти — мало, крышка только дребезжит. Скажите «Алохомора» — щёлк, искорки, крышка приподнимается щелью; дальше поднимите её рукой (подведите пальцы под край и поднимите). Запертая дверь дома жителя (такие запирают на ночь или когда никого нет дома) приоткроется — возьмитесь за ручку и откройте. Если кто-то из жителей видит, как вы вскрываете замок или берёте чужое, — это кража: хозяева (а в замке стража) пойдут на вас. Никто не видел — ничего не будет. Сундуки пещер и так открыты. Отпирает и дверь, запертую заклинанием «Lock». На людей и животных не действует.', dmg: '—', cost: 5, icon: 'assets/icons/alohomora.svg' },
    { cat: 'move', name: 'Lock', say: 'показать рукой (или палочкой) на дверь рядом, до 5 м + «Lock» («Лок», «Lock door»)', desc: 'Запирает дверь. Свиток не нужен — заклинание известно сразу. Открытая дверь сама плавно закрывается, щёлкает замок, у ручки вспыхивает огонёк. Пока кто-нибудь не скажет на неё «Алохомора», дверь никто не откроет: ни вы рукой (ручка не поддаётся, дверь только дребезжит), ни другие игроки, ни хозяева дома, ни рыцари, ни волшебники — люди постучат, подождут и пойдут другой дорогой. Работает на двери домов жителей и волшебников, на двери, поставленные игроком, и на ворота тронного зала. Это обычный замок, а не магическая защита: взрыв, оружие или огонь ломают дверь как обычную. Говорите отдельным словом. На людей, животных и вещи не действует.', dmg: '—', cost: 3, icon: 'assets/icons/alohomora.svg' },
    { cat: 'move', name: 'Алохомора Максима', say: 'показать рукой на ворота + «Алохомора Максима»', desc: 'Вне Творческого — только после свитка «Алохомора Максима» (медная лента) из сундука; обычная «Алохомора» известна сразу. Сильная «Алохомора» — для крепких замков. Ворота тронного зала в каждом замке: рыцари, король и слуги проходят свободно (ворота сами открываются перед ними и закрываются за ними), а перед вами они заперты. Простая «Алохомора» их не берёт. «Максима» отпирает — створки чуть приоткрываются, дальше толкайте их рукой. Ещё ворота можно разбить: два «Бомбардо», одно «Бомбардо Максима» или «Total Destruction». Стража, увидев взлом, нападёт. В захваченном вами замке ворота открыты для вас. Двери домов волшебников — позже.', dmg: '—', cost: 25, icon: 'assets/icons/alohomora.svg' },
    { cat: 'move', name: 'Атак', say: 'пока меч или топор парит («Вингардиум Левиоса») + «Атак»', desc: 'Оружие летит в ближайшее живое существо и вонзается в него (нет никого — летит туда, куда показывает рука). Раненый теряет 1 HP в секунду, течёт кровь. Вынуть оружие можно рукой, «Акцио» или «Левиоса» — кровь идёт вдвое медленнее, пока не скажут «Rescue».', dmg: '4–5 + кровь', pvp: '4–5 + 1 HP/с', icon: 'assets/icons/levitation.svg' },
    { cat: 'guard', name: 'Rescue', say: 'пальцы к своей ране + «Rescue» (или рукой на раненого)', desc: 'Останавливает кровотечение. Если оружие ещё в ране — вынимает и его.', dmg: '—', icon: 'assets/icons/shield.svg' },
    { cat: 'move', name: 'Вингардиум Левиоса', say: 'направить руку на предмет + «Вингардиум Левиоса»', desc: 'Предмет, животное, человек, другой волшебник или тело погибшего до 30 м поднимается там, где был, и следует за рукой. Живые в воздухе пугаются и вырываются: жители кричат и болтают руками и ногами, рыцари дёргаются, волшебник замка через несколько секунд сам вырывается и мягко опускается. Если не вышло — подсказка скажет почему (щит, защита дома, кто-то на пути, его уже держат). Резкий рывок — бросок: брошенный летит, машет руками и ногами, а ударившись о землю, стену или другого — падает, кувыркается, лежит и теряет здоровье тем больше, чем сильнее удар (рыцаря бережёт доспех). Сбивает с ног и того, в кого врезался.', dmg: '—', cost: 6, icon: 'assets/icons/levitation.svg' },
    { cat: 'move', name: 'Вингардиум Левиоса Максима', say: 'направить руку (или палочку) на людей, дерево, дом, стену, землю или корабль + «Вингардиум Левиоса Максима» («Левиоса Максима»)', desc: 'Сильная Левиоса (вне Творческого — из свитка с сиреневой лентой). Сразу 50 маны, потом 2 маны в секунду, пока держите: держится, сколько хватит маны. Поднимает всех вокруг того, на кого показали (до 7 м): игроков, жителей, рыцарей, волшебников, моряков, зомби, животных, паучиху, живые деревья — они висят и следуют за рукой. Корабль поднимается из воды целиком, с экипажем и всем на палубе. Дерево, дом, кусок стены или глыбу земли сами по себе не вырвать — их надо выкорчевать палочкой, как зуб: раскачивайте палочку туда-сюда (в стороны или вверх-вниз) и тяните вверх. Чем шире и бодрее раскачка и сильнее тяга, тем быстрее поддаётся; перестали раскачивать — снова садится на место; тяжёлое (большой дом) требует больше усилий. Оно шатается в такт палочке, трещит, сыплется земля и крошка, а расшатанное отрывается, когда тянете вверх. Дерево выходит с корнями и комом земли, дом — целиком (без корней), люди внутри — вместе с ним. Кусок стены замка, башни или забора (там, куда показывает палочка, около 3×3 блоков) и глыба земли (остаётся яма) несутся так же; стена самого дома — это дом, он вырывается целиком; под чужой сферой защиты — нельзя. Жители пугаются, а строители замка потом закладывают дыру. Резкий замах рукой — и дом, дерево, кусок стены или глыба летит, куда махнули, и разбивается о землю, стену, другой дом или того, в кого попал. «Стоп» или конец маны — всё падает: дом разлетается на куски и ложится грудой (сундуки выпадают целыми), дерево ложится, корабль разбивается, и кто под ним — ранен. Те же слова ещё раз — опустить бережно: дом встанет целым на новом месте, дерево — стоя. Магические доспехи от неё не спасают. Драконов, фениксов и книги-птицы не берёт.', dmg: 'падение 5–45', cost: 50, icon: 'assets/icons/levitation.svg' },
    // ---- build
    { cat: 'build', name: 'Gather', say: 'указать на дерево / камень / землю + «Gather» или «Assemble»', desc: 'Известно сразу, с начала игры — книга и свиток не нужны. Магия разбирает то, на что указывает рука (до 10 м), и кладёт в ячейку: дерево целиком — 20 древесины своего вида. Укажите на вещи на земле (например, у тела погибшего) — все вещи вокруг уйдут в ячейки.', dmg: '—', cost: 3, icon: 'assets/icons/gather.svg' },
    { cat: 'build', name: 'Create a Floor', say: 'выбрать ресурс + «Create a Floor», тянуть руку', desc: 'Пол растёт блок за блоком за рукой. С водяным шаром в руке — изо льда.', dmg: '—', cost: 4, icon: 'assets/icons/floor.svg' },
    { cat: 'build', name: 'Stitching', say: 'направить палочку (руку) на проход + «Stitching» («Стичинг»)', desc: 'Сшивает проход: дыру в пещере, проём без двери в доме или в стене замка, дыру в полу. Магия ищет самое узкое место прохода, которое со всех сторон окружено материалом (камнем, кирпичом, деревом) — если пустота ничем не окружена (поле, небо, широкий зал), магия не работает. Камни того же материала слетаются со стен и ложатся в проход один за другим, снизу вверх, со светящимися швами. Получается обычная твёрдая стена: сквозь неё не пройти, а «Бомбардо» её ломает. В человека или зверя камень не кладётся — ждёт, пока отойдёт. Без свитка.', dmg: '—', cost: 7, icon: 'assets/icons/wall.svg' },
    { cat: 'build', name: 'Create a Wall', say: '«Create a Wall», вести руку вбок и вверх', desc: 'Стена растёт за рукой — в ширину и в высоту.', dmg: '—', cost: 4, icon: 'assets/icons/wall.svg' },
    { cat: 'build', name: 'Create a Ceiling', say: '«Create a Ceiling», тянуть руку', desc: 'Потолок на высоте 3 блоков растёт над вами.', dmg: '—', cost: 4, icon: 'assets/icons/ceiling.svg' },
    { cat: 'build', name: 'Build a Roof', say: '«Build a Roof», тянуть руку', desc: 'Двускатная крыша: ступени от краёв к коньку.', dmg: '—', cost: 6, icon: 'assets/icons/roof.svg' },
    { cat: 'build', name: 'Create a Door', say: 'держа дерево (≥ 12) + «Create a Door»', desc: 'Кубик дерева превращается в дверь с ручкой; отводите руку — она растёт; покажите место и скажите «Stand».', dmg: '—', cost: 6, icon: 'assets/icons/door.svg' },
    { cat: 'build', name: 'Create a Bed', say: 'показать рукой или палочкой на брёвна и шерсть + «Create a Bed» / «Создай кровать»', desc: 'Бросьте рядом 4 бревна (дерево из руки) и 3 клубка шерсти (с баранов) — они должны лежать вместе, в 3 метрах друг от друга. Покажите на них и скажите слово: вспышка искр — и стоит белая кровать вдоль вашего взгляда. Чего-то не хватает — подсказка скажет, чего.', dmg: '—', cost: 6, icon: 'assets/icons/floor.svg' },
    { cat: 'build', name: 'Create a House', say: 'палочкой на брошенные шерсть и песок + «Create a House» / «Создай дом»', desc: 'Выучивается из свитка (янтарная лента; первый такой свиток найти легко — он часто лежит в сундуках, пока вы его не нашли). Бросьте рядом 3 шерсти и 10 песка (песок — «Gather» на пляже или у реки, потом бросок из руки), неподалёку должно расти хотя бы 3 дерева. Возьмите палочку, наведите на кучку и скажите слова: 10 секунд вспышек, вихря и пыли — деревья вокруг исчезают, песок становится стёклами, шерсть — кроватью, и встаёт домик с крышей: дверь, комната с кроватью, кладовая с пустым сундуком. Каждый дом немного другой. Всё время держите палочку: выпустили или кончилась мана — магия срывается и начинается пожар.', dmg: '—', cost: '20 + 0,5/с', icon: 'assets/icons/floor.svg' },
    { cat: 'build', name: 'Create a Castle', say: 'палочку туда, где встанет замок, + «Create a Castle» / «Создай замок» (слышится и как «криейт э касл»)', desc: 'Целый замок по мотивам замка Мираза из «Принца Каспиана»: тёмный камень, высокие тонкие башни с острыми шпилями и золотыми навершиями, ворота с надвратными башнями, двор, дворец с высоким тронным залом. Нужно 500 маны (в Творческом — бесплатно и без палочки) и камень рядом: скалы или каменная порода под землёй в ~35 м вокруг (обычно хватает всегда; на песчаном берегу или над водой — нет). Других предметов не нужно. Замок встаёт примерно в 45 м перед вами, воротами к вам, на ровном сухом месте без построек. 30 секунд: земля трясётся и грохочет, стены и башни вырастают из земли, камни вокруг поднимаются и летят в стены, потом сверху достраиваются зубцы, крыши и шпили. Всё это время держите палочку — выпустили, и магия замка останавливается (что успело вырасти — остаётся). Внутри: ворота и железные двери открываются руками, тронный зал с золотым троном, спальня с 4 кроватями, сокровищница с 3 пустыми сундуками — кладите в них свои вещи.', dmg: '—', cost: '500', icon: 'assets/icons/castle.svg' },
    { cat: 'build', name: 'Create an Ice Castle', say: '«Create an Ice Castle» («криейт эн айс касл», «айс касл», «создай ледяной замок»), потом топнуть ногой, потом поднять обе руки снизу вверх', desc: 'Способ Эльзы из «Холодного сердца». Нужна вода или снег рядом (река, озеро, море, снег — до 30 м). Скажите слова и топните ногой (поднять колено и резко поставить; если камера не видит ног — резко опустите обе руки вниз): от ноги по земле бежит ледяной пол-снежинка, 15 м вокруг. Затем поднимайте обе руки снизу вверх — замок растёт из пола вслед за руками: насколько подняты руки, настолько он вырос; опустили — ждёт; руки прямо вверх — купол сомкнулся, шпили выросли, замок готов. Внутри: ледяные ворота (открываются рукой), зал под куполом, лестница слева на галерею и балкон над воротами, ледяной трон, люстра-снежинка, кровать. Пока растёт — концентрация (другие заклинания не работают; «стоп» — что выросло, то остаётся). Огонь — слабость льда: «Инферно», «Fire Maxima», «Адский огонь» растапливают стены. Создать замок можно где угодно, но в тепле он простоит сутки, а ко концу вторых игровых суток растает весь (сверху вниз); в горах, где лежит снег, он не тает никогда.', dmg: '—', cost: 500, icon: 'assets/icons/ice.png' },
    { cat: 'build', name: 'Ice Bridge', say: 'показать рукой на место, куда вести мост + «Ice Bridge» («айс бридж», «создай ледяной мост»)', desc: 'Нужна вода или снег рядом (до 18 м). Покажите рукой на землю там, где мост должен кончиться (5–60 м: через обрыв, реку, яму — или просто так), и скажите слова: от ваших ног аркой растёт ледяной мост — вслед за рукой: держите руку на конце, и он дорастёт; опустили руку ближе — ждёт. Настил в 3 блока, ледяные перила со светящимися столбиками; по мосту ходят и люди, и звери. Огонь его растапливает; в тепле за пару игровых суток он тает сам, в горах в снегах — нет.', dmg: '—', cost: 50, icon: 'assets/icons/ice.png' },
    { cat: 'build', name: 'Improve a House', say: 'палочкой на ресурсы рядом с домом + «Improve a House» / «Улучши дом»', desc: 'Выучивается из свитка (белая лента). Выйдите из своего дома, бросьте рядом ресурсы и скажите слова: за 10 секунд дом снова меняется магией — больше, второй этаж, балкон; на 5-м уровне — большой каменный дом (камень берётся из-под земли сам). Каждый уровень вдвое дороже: уровень 2 — 6 шерсти, 20 песка, 4 дерева, 40 маны и 1 в секунду; 3 — 12, 40, 6 деревьев, 80 маны; 4 — 24, 80, 8, 160; 5 — 48, 160, 10, 320. Вещи в сундуках не пропадают. Новый уровень — не раньше чем через 3 минуты.', dmg: '—', cost: '40…320', icon: 'assets/icons/floor.svg' },
    { cat: 'build', name: 'Change a color', say: 'показать на кровать + «Change a color синий» / «Поменяй цвет на красный»', desc: 'Кровать (до 12 м) сразу перекрашивается: белый, красный, синий, зелёный, жёлтый, оранжевый, фиолетовый, розовый, голубой, чёрный, коричневый, серый.', dmg: '—', cost: 2, icon: 'assets/icons/lumos.svg' },
    { cat: 'build', name: 'Breakthrough', say: 'обе руки чуть ниже горизонта перед собой, потом поднять их вместе (за 3 с) + «Breakthrough»', desc: 'Из земли перед вами поднимается стена из камня и земли (5 блоков в ширину, 3 в высоту) — укрытие от заклинаний и зомби. Тех, кто стоял там (игроков, людей, зомби, животных), отбрасывает назад; Максима — сбивает с ног.', max: '«Breakthrough Максима»: стена 9 × 5 (мана 20).', dmg: '—', cost: 10, icon: 'assets/icons/wall.svg' },
    { cat: 'build', name: 'Fire', say: 'поднять руку, показать на землю (до 25 м) + «Fire» / «Файр» / «Костёр»', desc: 'Там, куда показывает рука, загорается костёр. Он горит 3 минуты, к концу затухает и гаснет. Ночью светится и освещает всё вокруг. Подержите у огня руку с древесиной: +1 минута за блок (до 10 минут). Мясо и рыба в огне жарятся. Стоять в костре горячо: −1 HP в секунду. На воде не горит.', dmg: '1/с, если стоять в огне', cost: 4, icon: 'assets/icons/inferno.png' },
    { cat: 'build', name: 'Stand', say: '«Stand» / «стоп»', desc: 'Закончить стройку: то, что растёт за рукой, встаёт на место. «Стоп» ещё и останавливает всё, что действует: щит, Левиосу, водяной шар, Люмос, огонь и лёд в руках, Акцио, полёт.', dmg: '—', icon: 'assets/icons/stand.svg' },
    // ---- wand only
    { cat: 'wand', name: 'Раскрой свои секреты', say: 'палочку (или просто руку) навести на предмет + «Раскрой свои секреты»', desc: 'Над предметом появляется голограмма: что это и какие у него свойства (сила, направление, особое заклинание…). Работает и без палочки — рукой. Без цели — рассказывает о предмете в руке или о самой палочке.', dmg: '—', icon: 'assets/icons/lumos.svg' },
    { cat: 'wand', name: 'Люмос', say: 'палочка в руке + «Люмос»', desc: 'Свет на конце палочки не мешает другим заклинаниям: пока Люмос горит, любое другое заклинание этой палочкой работает как обычно (свет остаётся). С руками V4 (настройки) палочку держат как ручку, и настоящую палочку, ручку или кисточку в вашей руке видит камера — палочка в игре повернётся как она. На кончике палочки загорается свет (понемногу тратит силу) и горит, пока вы его не погасите или не бросите. Бросить свет: замахнитесь палочкой назад и резко бросьте вперёд (случайный рывок рукой свет не сбросит) — свет срывается с палочки и летит туда, куда вы бросили: понемногу замедляется, мягко отскакивает от стен, пола и потолка (в пещере летит дальше по ходу), зависает в воздухе и гаснет секунд через 15 (палочка остаётся в руке); «Люмос» — зажечь снова. «Нокс» или «стоп» — погасить всё, и брошенный свет тоже.', max: '«Люмос Максима» — ярче; скажите ещё раз — ещё ярче (до ×5), но и сил тратит больше.', dmg: '—', cost: 2, icon: 'assets/icons/lumos.svg' },
    { cat: 'wand', name: 'Lightning Writing', say: 'палочка в руке + «Лайтнинг Райтинг» (Lightning Writing)', desc: 'Рисуйте палочкой в воздухе: за кончиком остаются светящиеся линии её цвета. Рисунок держится около 10 секунд и тускнеет; другие игроки его тоже видят.', dmg: '—', icon: 'assets/icons/lumos.svg' },
];

export const ITEM_CATEGORIES = [
    { id: 'weapon', name: '⚔️ Оружие и защита' },
    { id: 'magic', name: '🪄 Волшебные вещи' },
    { id: 'things', name: '🎒 Вещи и еда' },
    { id: 'potions', name: '🧪 Зелья' },
    { id: 'world', name: '🐾 Существа и места' },
];

/**
 * One card per thing: a magic kind of it is a «✨ Волшебный» line on the same card
 * (not a card of its own). How the game works (mana, health, death…) is not an item —
 * it is in MECHANICS («Механика игры»). An item without a cat shows under «Вещи и еда».
 */
export const ITEMS = [
    { cat: 'weapon', name: 'Меч', desc: 'Берётся рукой как настоящий: поднесите открытую ладонь к рукояти и сожмите пальцы. Урон и отбрасывание зависят от силы и направления замаха. Режет зомби на части, колющим ударом вонзается. Клинки игроков не проходят друг сквозь друга — звенят и держат удар; пробьёт только намного более сильный замах. Режущий удар оставляет порез, который заживает сам.', magic: 'слегка светится, бьёт сильнее на 1–60% и разбивает обычный «Protection», которого коснётся.', dmg: '2 (сильный замах — больше)', pvp: '2–3', icon: 'assets/icons/sword.png' },
    { cat: 'weapon', name: 'Топор', desc: 'Тяжёлый острый топор. Берётся и бьёт как меч, но из-за веса сильнее пробивает чужой блок.', magic: 'как у меча: светится, бьёт сильнее на 1–60% и разбивает обычный «Protection».', dmg: '3 (сильный замах — больше)', pvp: '3–4', icon: 'assets/icons/axe.png' },
    { cat: 'weapon', name: 'Лук и стрелы', desc: 'Лук в одной руке — он сам смотрит туда, куда вытянута рука. Поднесите к луку другую руку (или достаньте стрелу из-за плеча) — стрела на тетиве. Сожмите кулак, отведите руку назад к подбородку (чем дальше — тем сильнее) и разожмите пальцы — стрела летит туда, куда вытянута рука с луком. Лук — в любой руке; вторая рука должна быть свободна. В Творческом режиме стрелы не кончаются; в других режимах с луком 10 стрел (до 25).', magic: 'бьёт на 1–60% сильнее.', dmg: '2–9', pvp: '2–9', icon: 'assets/icons/sword.png' },
    { cat: 'weapon', name: 'Щиты', desc: 'Деревянный, железный, рыцарский. Держите в руке перед собой — заклинания и удары спереди остаются на щите. Обычный щит разбивается сильным заклинанием. В Творческом — на пьедесталах.', magic: 'своя сила 20–50 (восстанавливается); ломается, только когда почти выдохся.', icon: 'assets/icons/shield.svg' },
        { cat: 'magic', name: '❄️ Ледяной Жезл', desc: 'Посох Ледяной Королевы — один во всём мире, выпадает, когда она побеждена. Это не палочка: держится в кулаке, как посох. Направьте кристалл на существо и скажите «Frozen» — оно замерзает, даже если на нём магические доспехи или мантия (12 маны; поднятый щит «Protection» отбивает). Направьте на землю, стену или воду и скажите «Frozen» — там встаёт слой льда (4 маны); ещё раз туда же — следующий слой: так строят ледяные стены и мосты, вода покрывается льдом. Этот лёд тает только от огня. Злые снеговики рядом слушаются хозяина жезла: идут за ним, а на «Атака» нападают на того, на кого показывает жезл.', icon: 'assets/icons/ice.png' },
        { cat: 'weapon', name: 'Молот Тора', desc: 'Только в грозу: поднимите молот над головой — в него ударит молния; за 5 секунд наведите его на цель. Вас не ранит никогда. 7 маны. Удачно — можно ещё (до 3 раз за грозу); промах — ждите следующей грозы. Гроза: раз в 5 минут с шансом 17%, длится 2–3 минуты.', dmg: '20', pvp: '12', cost: 7, icon: 'assets/icons/thunder.png' },
    { cat: 'magic', name: 'Палочка', desc: 'У каждого волшебника с самого начала есть обычная деревянная палочка: заклинания с ней на 15% сильнее. Её держат как ручку — палочка смотрит туда, куда указательный палец. Настоящая палочка, ручка или кисточка в вашей руке тоже видна камере — палочка в игре повернётся как она.', magic: 'только в сундуках в пещерах (и всегда — у побеждённой паучихи). 10 видов, у каждой свой цвет и свои тайны: заклинания +15% сильнее и −15% маны; направление (дуэль / разрушение / собирательство / строительство) +25%; особое заклинание +40%; своя сила 1–50%. Узнать — «Раскрой свои секреты».', icon: 'assets/icons/lumos.svg' },
        { cat: 'magic', name: '🐉 Палочка дракона', desc: 'Остаётся от побеждённого дракона. Очень красивая: тёмно-алое дерево, по нему чешуйки, на конце чёрный коготь держит светящийся уголёк. Все огненные заклинания с ней на 60% сильнее: «Инферно», «Fire» (костёр горит дольше), «Fire Maxima», «Let the Hellfire Come». Маны — как обычно. Остальные заклинания — на 15% сильнее, как с любой палочкой.', dmg: 'огонь +60%', icon: 'assets/icons/inferno.png' },
    { cat: 'magic', name: '🌟 Костюм Высшего мага', desc: 'Тёмно-синий длинный камзол с плащом: золотые узоры, золотой пояс с сапфиром, светящиеся голубые руны. Даётся только тем, кто получил все ачивки, — появляется у вас в ячейке с золотой вспышкой. Наденьте руками: приложите к груди. Защищает как волшебная мантия (холод и простейшие заклинания не берут) и сверх того любое заклинание ранит на 40% слабее. Не слетает от «Disarmor»; при смерти падает рядом с телом, как всё остальное (его можно забрать). Надеть его может только Высший маг. В сундуках и у торговцев его нет.' },
    { cat: 'magic', name: 'Свиток', desc: 'Подожгите его в руке («Инферно»): +1–5 здоровья или +1–10 маны. Свитки «Lightning Strike» (золотая лента), «Thunderwave» (синяя), «To the Sun» (оранжевая), «Alive» (коричневая), «Let it rain» (серебряная), очень редкий «Авада Кедавра» (зелёная) и самый редкий «Total Destruction» (чёрная) учат эти заклинания — вне Творческого режима без свитка их нет. Действует на того, кто сжёг, и в «Выживании» тоже (здоровье там растёт и сразу лечит). Прочитать может каждый: поднесите вторую (пустую) руку раскрытой к концу свитка и сожмите пальцы на валике, потом разведите руки — он развернётся между ними; сведите — свернётся между руками; разожмите вторую руку — она отпустит валик, и свиток снова свёрнут в первой руке. Его можно бросить или убрать в карман.', dmg: '—', icon: 'assets/icons/inferno.png' },
        { cat: 'magic', name: '📜 Свитки богов', desc: 'Четыре древних свитка лежат только в одном месте — в библиотеке заброшенного храма богов на Венере, каждый парит над своим пьедесталом: «Create a Planet» (синяя лента со звёздами) — создать планету, «Enlarge Planet» (коралловая) — увеличить планету, «Terraform Planet» (изумрудная) — терраформировать планету, «Wingardium Leviosa Super Maxima» (жемчужная) — двигать планету в космосе. Берутся рукой, раскрываются другой рукой, как любой свиток; выучит заклинание тот, кто сожжёт свиток («Инферно»). Первое использование каждого из этих четырёх заклинаний даёт +100 ячеек маны. Взятый свиток через полторы минуты снова появляется на своём пьедестале — хватит всем игрокам.' },
    { cat: 'magic', name: 'Книга заклинаний', desc: 'Падает с птицы-книги, если сбить её заклинанием. В руке её держат как настоящую: край книги между большим пальцем и остальными, пальцы лежат на обложке и не проходят сквозь страницы. Её можно бросить, убрать в карман, передать. Второй рукой возьмите книгу за край обложки (сожмите пальцы) и разведите руки — книга раскроется настолько, насколько разведены руки; наклоните кисти — наклонится и книга. Разожмёте руку ладонью вверх — книга ляжет на ладонь; упадёт она, только если разжать вытянутую руку. Чтобы листать, отпустите одну руку, подденьте кончиком указательного пальца край страницы и переведите её на другую сторону; отпустили раньше середины — страница ляжет обратно. Прочитанное заклинание выучено. Сожжёте книгу («Инферно» с книгой в руке, пламя или огонь) — выучите все её заклинания.', icon: 'assets/icons/gather.svg' },
    { cat: 'magic', name: '📘🛡️ Книга защиты (летающая)', desc: 'Особая книга-птица: тёмно-синяя обложка с серебряной каймой, серебряный щит на каждой обложке и слабое голубое сияние вокруг. Встречается так же часто, как обычные книги-птицы. Её бережёт магия: «Авада Кедавра», все дуэльные заклинания, лучи, взрывы, стрелы, «Левиоса», ветер отскакивают от её сияния искрой. Сбить её можно только прямым попаданием огня (пламя «Инферно», «Let the Hellfire Come») или ледяным шаром: наберите «Waterbollow», заморозьте его «Frozen» и бросьте (или ударьте) в книгу. Упавшая книга чуть опалена, но читается. В ней группа «Защита дома» — Protection House, Protection Invisible, Protection House Grant: прочитали страницу любого из них — выучили все три. В свитках, сундуках и лавках этих заклинаний нет. В Творческом режиме книга лежит на пьедестале.', icon: 'assets/icons/ward.svg' },
    { cat: 'magic', name: '📘 Быстрая летающая книга', desc: 'Особая книга-птица: голубая обложка, серебряная кайма, за ней тянется голубой след. Летает так же, как обычные, только вдвое быстрее и юрче; встречается в четыре раза реже обычной. Сбивают и ловят её так же (заклинание, стрела, «Левиоса», «Акцио»). В её книге одно заклинание — «Флайн». Раскрыть и прочитать её можно, но выучит «Флайн» только тот, кто её сожжёт: держите книгу в руке и скажите «Инферно», направьте на неё пламя или подержите её в огне (костёр, горящее дерево) — она сгорит, и вы научитесь летать. Только она учит «Флайн» (свитков полёта больше нет). В Творческом режиме она лежит на пьедестале.', icon: 'assets/icons/flight.svg' },
    { cat: 'magic', name: '💎 Кристалл маны', desc: 'Светящиеся голубые кристаллы растут глубоко в пещерах (не у входа), редко, кучками по 3–5. Взять: протяните к кристаллу открытую ладонь и сожмите пальцы — он отломится в руку (сжать можно рядом с ним, не обязательно точно на нём; кулак, просто ткнувшийся в кристалл, ничего не берёт; рука с палочкой или другой вещью кристалл не возьмёт — возьмите свободной рукой); «Gather» на кучку — все в ячейки; «Акцио» — по одному. Разломить: держа кристалл в одной руке, обхватите его второй (обе руки сжаты на нём), затем разведите руки сантиметров на 20–25 в стороны или поверните их друг против друга — он рассыпается искрами, максимум маны +5. Для этого обе руки должны быть свободны (палочку уберите). В Творческом режиме один лежит на пьедестале.', icon: 'assets/icons/lumos.svg' },
    { cat: 'things', name: '💰 Мешочек с монетами', desc: 'Кожаный мешочек, стянутый у горловины пеньковым шнурком с узелками; внутри звенят монеты. Лежит в сундуках, выпадает у рыцарей и короля, его даёт торговец, когда вы что-то продаёте. Держат за горловину, в кулаке. Привязать к поясу: посмотрите вниз и левой рукой с мешочком дотянитесь до правого бока (у левши — наоборот). В мешочке до 100 монет, на поясе до трёх мешочков (300 монет). Им платят на прилавке, его можно отдать или бросить; при смерти мешочки падают рядом.', dmg: '—', icon: 'assets/icons/gather.svg' },
        { cat: 'things', name: '✨ Магический мешочек', desc: 'Заколдованный мешочек с незримым расширением: красный бархат с золотыми рунами, горловина завязана золотой шёлковой ленточкой с бантом, по нему пробегают искорки. В него влезает СКОЛЬКО УГОДНО монет, а снаружи он остаётся небольшим. Всё как с обычным: держат за горловину, привязывают к поясу, снимают, отдают, бросают. Если он на поясе, обычные мешочки, приложенные к нему, высыпаются в него (лимита 300 монет больше нет). Платите им на прилавке — торговец возьмёт из него только цену, а сам мешочек останется вашим. При смерти падает целиком, со всеми монетами. Где взять: у мастера котлов и зелий в башне волшебников (иногда лежит на прилавке, 750 монет) или изредка в сундуках как ценная вещь. В «Творческом» он у героя с самого начала.', dmg: '—', icon: 'assets/icons/gather.svg' },
        { cat: 'things', name: 'Рюкзак', desc: 'Возьмите в руку и заведите обе руки за спину — рюкзак надет: +3–5 ячеек.', dmg: '—', icon: 'assets/icons/gather.svg' },
    { cat: 'things', name: '🍎 Еда', desc: 'Поднесите еду ко рту и подержите — съедите (здоровье не поднимается выше полного: сытый не ест). Яблоко (с обычных яблонь, их много) +3 HP; золотое яблоко (с редких золотых деревьев) +10 HP. С рынка: хлеб и сыр +3, пирог +5. Мясо — с туши животного (рукой или «Gather»), сырое: баранина +6, свинина +7, говядина и конина +8, бык +9, минотавр +10. Жареное — вдвое больше (+12…+20): положите мясо в костёр («Fire») или подержите в пламени 3 секунды, или обожгите огнём заклинания — «Инферно», «Адским огнём» — около секунды. Рыба тоже жарится. В ячейке до 10.', icon: 'assets/icons/gather.svg' },
        { cat: 'things', name: '🪵 Брёвна', desc: 'Выберите ячейку с древесиной (кубик в правой руке) и сделайте бросок — замах, взмах и разжать пальцы: вылетает связка из 4 брёвен. Коснитесь связки рукой — дерево вернётся в ячейку.', dmg: '—', icon: 'assets/icons/gather.svg' },
        { cat: 'things', name: '🧶 Шерсть', desc: 'Остаётся от барана: 2–3 клубка. Возьмите рукой — до 20 в ячейке. Нужна для кровати (3 клубка) — бросьте её рядом с брёвнами.', dmg: '—', icon: 'assets/icons/gather.svg' },
    { cat: 'potions', name: '🫕 Котёл', desc: 'Большой чёрный железный котёл — выше пояса героя и шире, чем высокий, на трёх коротких ножках, с ручками. Купить — у мастера котлов и зелий: его лавка у одного из домиков волшебников рядом с Академией (не в самой башне). Возьмитесь за котёл — мастер назовёт цену (150 монет), скажите «да». Унесёте не заплатив — вор! Иногда старый ржавый котёл находится в пещере, часто перевёрнутый. Котёл тяжёлый: толкайте его двумя ладонями или возьмитесь обеими руками за край / ручки и тяните. Сильный толчок двумя руками высоко — опрокинется (и всё выльется). Поставить: обе руки на край или ручки и поднимайте — отпустите рано, упадёт обратно. «Вингардиум Левиоса» тоже поднимает его. В Творческом режиме котёл стоит справа от пьедесталов.', dmg: '—', icon: 'assets/icons/gather.svg' },
    { cat: 'potions', name: '🧪 Как сварить зелье', desc: '1) Костёр: «Fire». 2) Котёл на костёр: подтащите его руками (или «Левиосой») прямо на огонь — появится тренога с цепями, котёл повиснет над пламенем. 3) Вода: у реки «Waterbollow» (с «Максимой» шар больше), принесите шар и резко дёрните рукой над котлом — вода выплеснется в него. Воду можно налить и заранее — это не ингредиент, а основа. 4) Ждите кипения (секунд 15): сначала пар, потом пузырьки, потом бурлит. 5) Ингредиенты: бросьте их или разожмите руку над котлом (можно и «Левиосой» поднести) — порядок любой, но с первого ингредиента идёт отсчёт: все нужно бросить за 30 секунд. В холодную воду вещь просто тонет и не считается. 6) Варится от 30 секунд до минуты, цвета меняются. 7) «🧪 Зелье готово!» — цвет каждый раз свой (по цвету зелье не узнать). Не успели, огонь погас, котёл сняли с костра или ингредиенты не те — серая жижа: опрокиньте котёл руками и начните заново.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '⚗️ Колба', desc: 'Пустые колбы продаёт мастер котлов и зелий (3 за 15 монет). Черпают руками: возьмите колбу и опустите руку с ней в котёл, чтобы колба ушла под поверхность зелья, — она наполнится. Из полного котла выходит до 10 колб, и с каждой зелья всё меньше — уровень опускается, руку нужно опускать глубже. В простую воду или в жижу окунать бесполезно. Выпить: поднесите колбу ко рту и подержите, как еду; пустая колба останется в руке.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '❤️ Зелье исцеления', desc: 'Рецепт: в кипящий котёл — 1 золотое яблоко и 1 кристалл маны. Выпить: +30 HP.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '👻 Зелье невидимости', desc: 'Рецепт: в кипящий котёл за 30 секунд — связка паутины, рог Минотавра и осколки стекла (порядок любой). Что оно делает — автор скоро расскажет; сварить и разлить по колбам уже можно, выпить пока нельзя.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '🕸️ Связка паутины', desc: 'Остаётся от гигантской паучихи, когда её победят. Серебристо-белый клубок липкой паутины. Ингредиент зелья невидимости.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '🥚 Яйцо дракона', desc: 'Лежит в логове дракона, на его золоте: у каждого дракона своё яйцо, цвета его дракона, в чешуйках, чуть светится изнутри. Большое и тяжёлое: держат одной рукой или двумя. В карман не влезет — заведите руку с ним за плечо, оно уйдёт за спину. Возьмёте яйцо — дракон проснётся. Пригодится для зелий. Дракон из него не вылупляется.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'potions', name: '🪶 Перо феникса', desc: 'Остаётся, если убить феникса: он сгорает в собственном пламени, и перо медленно опускается на землю. Длинное, от тёмно-алого у основания до светящегося золотого кончика, чуть искрится. Берётся рукой за стержень, кладётся в ячейку или в карман. Понадобится для зелий — позже; сейчас оно ничего не делает.', dmg: '—', icon: 'assets/icons/water.svg' },
    { cat: 'things', name: '🪶 Перо совы', desc: 'Остаётся от умной волшебной совы, если её убить заклинанием со свитка. Мягкое, переливается всеми цветами, как мыльный пузырь. Берётся рукой за стержень, кладётся в ячейку или в карман.', dmg: '—', icon: 'assets/icons/gather.svg' },
    { cat: 'potions', name: '🔷 Осколки стекла', desc: 'Разбейте окно в доме жителей (сильным заклинанием или настоящим ударом) — стекло выпадет под окно, возьмите его. Ингредиент зелья невидимости. (Жители не любят, когда бьют их окна!)', dmg: '—', icon: 'assets/icons/water.svg' },
        { cat: 'world', name: '🕷️ Гигантская паучиха (босс)', desc: 'Выходит из темноты раз за ночь (в «Выживании» и «Хардкоре»), на рассвете уходит. Огромная — около 8 м в высоту, бегает быстро и хватает издалека. 200 HP. Каждые 15 с плюёт ядом (−7), каждые 7 с — паутиной (4 с не двинуться), раз в 30 с может схватить (44%) и кусать (−5 каждые 5 с) — освобождает только «Protection Maxima». Ветер её не сдувает, лёд не морозит, «Авада Кедавра» снимает лишь 20. Побеждённая оставляет сокровища — всегда волшебную палочку.', dmg: '—', icon: 'assets/icons/avada.svg' },
        { cat: 'world', name: '🐉 Драконы', desc: 'Редкие. Пять видов, у каждого свой вид: изумрудный лесной, багровый огненный, чёрный обсидиановый (самый большой), золотой пустынный, ледяной синий. Сила дракона — быстрота и сила пламени: зависит от вида и от случая. У каждого 1000 HP. Огонь ему не страшен совсем — ни «Инферно», ни «Fire Maxima», ни адский огонь. «Авада Кедавра» только ранит (−25), «Остолбеней» оглушает на секунду, лёд замедляет, песок слепит, молния и взрывы бьют сильно; мечи, топоры и стрелы — слабо (толстая чешуя). «Левиоса» его не поднимет, «Брейнрот» не действует, ветер лишь качнёт. Дышит огнём (щит «Protection» и вода его держат), кусает, бьёт хвостом. Живёт в логове и стережёт золото; иногда пролетает высоко в небе — по земле бежит его тень, а бывает, садится отдохнуть. Не трогайте — не тронет. Побеждённый оставляет палочку дракона.', dmg: 'пламя, укус −14, хвост −9', icon: 'assets/icons/inferno.png' },
        { cat: 'world', name: '⛰️ Логово дракона', desc: 'Особая огромная пещера высоко в больших горах — поднимайтесь на гору. Вход — огромный, в склоне горы: оттуда дракон выходит и взлетает. Внутри большой зал, а в нём куча золота: от 1000 до 5000 монет. Часть в мешочках (не полных, есть и пустые), остальное — горой. Монеты из кучи берут руками: открытую ладонь в кучу и сжать пальцы — горсть; поднести к открытому мешочку в другой руке и разжать — монеты в мешочке (до 100). Или, глядя вниз, разжать левую руку у мешочков на правом боку — в мешочки на поясе (у левши — правую руку у левого бока). Здесь же яйца драконов. Дракон спит на золоте: подкрадывайтесь без света и не бегите. Возьмёте золото или яйцо — проснётся сразу. Убежите из логова — вылетит следом, но далеко от дома не полетит.', dmg: '—', icon: 'assets/icons/earthquake.svg' },
        { cat: 'world', name: '🔥 Феникс', desc: 'Редкая красивая огненная птица ростом в полгероя: алое с золотом оперение, хохолок, длинный струящийся хвост с золотыми «глазками», за ней в полёте тянутся искры, ночью она светится тёплым светом. Фениксы — одиночки: в округе не больше одного. Почти всё время парят высоко в небе широкими кругами, иногда садятся на вершину горы или высокое дерево. Если вы ранены (потеряли здоровье, кровоточите, лишились руки или ноги) и феникс рядом, с шансом 9% он прилетит: сядет в нескольких шагах перед вами и будет смотреть. Стойте спокойно — не двигайтесь, не машите руками, не поднимайте руку для заклинания. Через пару секунд он подойдёт, коснётся вас головой и раскроет над вами крыло — золотой свет, тихая песня, и вы исцелены полностью: всё здоровье, кровь остановлена, оружие из ран вышло, отрубленные руки и ноги отросли, лёд, оглушение и головокружение прошли. Испугаете — отпрянет, испугаете трижды — улетит. На него можно напасть (мечом, стрелой, кулаком, заклинаниями; огонь и лёд его не берут) — обычно он улетает высоко. Но если упорно пытаться его убить, он может вспыхнуть огнём и бросаться на вас сверху, ударяя пламенем (−5, трава и деревья там загораются); спасает щит «Protection» или вода. К тому, кто нападал на фениксов, они долго не прилетают лечить. Убитый феникс сгорает и оставляет перо феникса. 30 HP.', dmg: '—', icon: 'assets/icons/avada.svg' },
        { cat: 'world', name: '🦉 Умная сова', desc: 'Волшебная сова ростом в четверть героя, оперение переливается всеми цветами. Встречается вдвое чаще фениксов: летает низко и часто садится на землю, камни, деревья. Людей не боится: подойдите к сидящей — она повернёт голову и с любопытством посмотрит на вас. Бросьте рядом мясо (любое, сырое или жареное) — съест и полюбит вас (над ней появятся сердечки). Тогда, пока она рядом, скажите, кого хотите найти: «я хочу найти дракона», «где паучиха», «покажи Ледяную королеву»… Она полетит и покажет дорогу к главному боссу — но только один раз. Простые заклинания на неё не действуют — она просто улетает; кто её обидит, того она больше не любит.', dmg: '—', icon: 'assets/icons/gather.svg' },
        { cat: 'world', name: '🐄 Животные', desc: 'Коровы, свиньи, бараны, кони ходят стадами по 3–8 — свободно, не толкаясь: щиплют траву, лежат, оглядываются, идут за вожаком; от испуга убегают всем стадом; идёте прямо на животное — оно отходит, приручённый конь сам подходит к хозяину. Ударите — защищаются (65%) или убегают; бараны заступаются друг за друга. Туша: мясо рукой или «Gather» (сырое +2 HP, жареное «Инферно» или на костре +4). Коня приручает яблоко — обычное красное или золотое (30% за яблоко, до 90%): прыжок рядом (или клавиша J) — вы верхом, шагайте на месте — едете вдвое быстрее. <b>Свиньи</b> с крыльями: испугаете — взлетают и улетают, иногда целое стадо пролетает высоко над миром. <b>Бык</b>: почти в половине коровьих стад вожак — с виду обычная корова; нападёте на стадо — он вырастает вдвое и становится медным огненным быком (разбег сбивает с ног, вблизи пышет огнём), убитый оставляет бронзовый рог. <b>Минотавр</b>: в каждой третьей отаре вожак-баран за 5 секунд встаёт на задние ноги и становится Минотавром (40 HP), убитый оставляет «Рог Минотавра». <b>Пегас</b>: в каждом пятом табуне — единственный чёрный конь с крыльями; защищает табун с воздуха. Он ничей и не приручается, но яблоко, скормленное рукой, может уговорить его подпустить вас: обычное — 9%, золотое — 40% за яблоко (иначе не даёт сесть). Верхом шагайте — идёт; хлопните его рукой по голове — взлетит (смотрите вверх/вниз — выше/ниже; присесть — сядет); слезете — уйдёт к табуну.', dmg: '—', icon: 'assets/icons/gather.svg' },
        { cat: 'world', name: '📕 Бегущая книга', desc: 'Редкая весёлая книга на ножках (встречается в три раза реже книг-птиц). Это не книга заклинаний: у неё одно-единственное действие — бег на 30% быстрее. Бегает очень быстро, но устаёт; убегает от людей, отскакивает в сторону, прячется за деревьями и камнями, останавливается оглядеться. Поймать можно только руками: наклонитесь, раскройте ладонь и сожмите её прямо на книге, когда она пробегает (можно двумя руками). Пойманная книга остаётся в руке: раскройте её двумя руками — у неё одна страница; прочитаете её — книга отдаст свою быстроту (бег на 30% быстрее) и исчезнет в золотых искрах. Только один раз — вторая книга уже ничего не даст и вырвется. После смерти прибавка пропадает. Заклинания действуют на неё как на зверя: «Левиоса» поднимет, «Остолбеней» остановит, «Акцио» притянет к ногам — тут и хватайте.', dmg: '—', icon: 'assets/icons/accio.svg' },
        { cat: 'world', name: '🏰 Замки', desc: 'Встречаются по всему миру (в «Творческом» режиме и «Выживании»), каждый свой: величественные, тесные, крепости; разный камень, крыши, цвета. Вокруг — деревня, поля и рынок перед воротами. Внутри донжона — тронный зал с королём и 10–15 комнат (кухня, трапезная, оружейная, сокровищница, часовня, библиотека, спальни, покои короля). Стены можно разрушить «Бомбардо». На мини-карте — 🏰.', dmg: '—', icon: 'assets/icons/wall.svg' },
        { cat: 'world', name: '👑 Жители, стража и король', desc: 'Жители (строители, фермеры, торговцы) никого не трогают. Если кто-то увидит, что вы обижаете жителя или стражника (или раненый выживет и расскажет) — рыцари нападут, люди разбегутся. Ударите короля — сбегутся все рыцари замка. Доспехи: у рыцаря 50, у короля 100 очков — сердечки убывают в разы медленнее. Победите короля — замок ваш: сундуки откроются, жители кланяются.', dmg: 'рыцарь 3, король 5', icon: 'assets/icons/avada.svg' },
];

